// Daftar domain tepercaya (Allowlist). Ubah sesuai kebutuhan.
const ALLOWLIST = [
  'google.com',
  'github.com',
  'microsoft.com',
  'linkedin.com',
  'anthropic.com'
];

const j = $json;
let raw = '';
let name = '';
if (j.from && j.from.value && j.from.value[0]) {
  raw = j.from.value[0].address || '';
  name = j.from.value[0].name || '';
}
if (!raw) {
  raw = (typeof j.from === 'string' ? j.from : (j.from && j.from.text)) || j.From || j.sender || '';
}
const m = String(raw).match(/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i);
const email = m ? m[0].toLowerCase() : '';
const domain = email.split('@')[1] || '';

// Subdomain ikut dianggap tepercaya (mis. mail.google.com)
const trusted = domain !== '' && ALLOWLIST.some(d => domain === d || domain.endsWith('.' + d));

let body = j.text || '';
if (!body && j.html) {
  body = String(j.html)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}
if (!body) body = j.snippet || '';
body = String(body).replace(/\s+/g, ' ').trim().slice(0, 4000);

return {
  json: {
    email_id: j.id,
    thread_id: j.threadId,
    sender_name: name,
    sender_email: email || String(raw),
    sender_domain: domain,
    subject: j.subject || j.Subject || '(tanpa subjek)',
    body: body || '(kosong)',
    is_trusted: trusted
  }
};

