const THRESHOLD = 6;

// Data email asli (dipasangkan otomatis dengan item hasil AI)
const src = $('Ekstrak Domain Pengirim').item.json;

const text = String($json.text || $json.output || '').trim();

// Ekstrak skor: prioritas pola "SKOR_RISIKO: 8", cadangan pola "8/10"
let score = null;
const patterns = [
  /SKOR[_\s-]*RISIKO\s*[:=\-]?\s*\**\s*(\d{1,2}(?:[.,]\d+)?)/i,
  /(\d{1,2}(?:[.,]\d+)?)\s*\/\s*10\b/
];
for (const p of patterns) {
  const mt = text.match(p);
  if (mt) {
    const n = Number(mt[1].replace(',', '.'));
    if (!Number.isNaN(n) && n >= 1 && n <= 10) {
      score = Math.round(n * 10) / 10;
      break;
    }
  }
}

// Alasan dari AI
let reason = '';
const rm = text.match(/ALASAN\s*[:\-]\s*([\s\S]*)/i);
reason = (rm ? rm[1] : text).trim().slice(0, 600);

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const parseOk = score !== null;
const scoreLabel = parseOk ? score + '/10' : 'tidak terbaca (perlu cek manual)';

const telegram_message =
  '🔎 <b>Tinjauan Email Diperlukan</b>\n\n' +
  '<b>Pengirim:</b> ' + esc(src.sender_email) + '\n' +
  '<b>Subjek:</b> ' + esc(src.subject) + '\n' +
  '<b>Skor risiko:</b> ' + esc(scoreLabel) + '\n' +
  '<b>Analisis AI:</b> ' + esc(reason || '(tidak ada respons AI)') + '\n\n' +
  '<i>Skor ≤ ' + THRESHOLD + ' sehingga tidak diberi label Phishing otomatis. ' +
  'Email TIDAK dihapus, mohon periksa manual di Gmail.</i>';

return {
  json: {
    ...src,
    risk_score: score,
    parse_ok: parseOk,
    ai_reason: reason,
    ai_raw: text,
    telegram_message
  }
};

const THRESHOLD = 6;

const labels = $input.all().map(i => i.json).filter(l => l && l.id && l.name);
const target = labels.find(l => String(l.name).trim().toLowerCase() === 'phishing');
if (!target) {
  throw new Error('Label "Phishing" tidak ditemukan di Gmail dan gagal dibuat otomatis. Buat label bernama Phishing secara manual lalu jalankan ulang.');
}

// Hanya email dengan skor > ambang yang diberi label
const emails = $('Ekstrak Skor Risiko').all()
  .filter(i => i.json.risk_score !== null && i.json.risk_score > THRESHOLD);

return emails.map(i => ({
  json: {
    email_id: i.json.email_id,
    label_id: target.id,
    subject: i.json.subject,
    risk_score: i.json.risk_score
  }
}));
